INSERT INTO "Jobs" ("Id", "BusinessId", "Title", "Description", "CategoryId", "TagsJson", "Status", "SalaryMin", "SalaryMax", "DurationType", "DurationDays", "RequiredSkillsJson", "ExperienceLevel", "SpotsTotal", "SpotsFilled", "Location", "IsRemote", "IsFeatured", "Deadline", "PublishedAt") VALUES
('950e8400-e29b-41d4-a716-446655440001', '750e8400-e29b-41d4-a716-446655440001', 'Frontend Developer (React + Tailwind)', 'Cần nhà phát triển Frontend để xây dựng giao diện website e-commerce. Yêu cầu: React, TypeScript, Tailwind CSS. Dự án kéo dài 2 tuần, 20 giờ/tuần.', '850e8400-e29b-41d4-a716-446655440001', '["React", "Frontend", "E-commerce"]', 'open', 2500000, 4000000, 'short-term', 14, '["React", "TypeScript", "Tailwind CSS"]', 'intermediate', 2, 1, 'Hồ Chí Minh', true, true, ((now())::date + interval '5 day'), now()),
('950e8400-e29b-41d4-a716-446655440002', '750e8400-e29b-41d4-a716-446655440004', 'Fix Bug Python Flask API - E-commerce', 'Ứng dụng Flask gặp lỗi trong xử lý thanh toán. Cần debug và khắc phục trong 3 ngày. API kết nối với database PostgreSQL.', '850e8400-e29b-41d4-a716-446655440001', '["Python", "Backend", "Debug"]', 'open', 2000000, 3500000, 'micro', 3, '["Python", "Flask", "PostgreSQL"]', 'advanced', 1, 0, 'Remote', true, false, ((now())::date + interval '3 day'), now()),
('950e8400-e29b-41d4-a716-446655440003', '750e8400-e29b-41d4-a716-446655440001', 'Xây dựng REST API với Node.js', 'Phát triển REST API cho ứng dụng quản lý dự án. Stack: Node.js, Express, MongoDB. Dự kiến 1 tháng.', '850e8400-e29b-41d4-a716-446655440001', '["Node.js", "Backend", "API"]', 'open', 4000000, 6000000, 'project', 30, '["Node.js", "Express", "MongoDB"]', 'intermediate', 1, 0, 'Remote', true, false, ((now())::date + interval '10 day'), now()),
('950e8400-e29b-41d4-a716-446655440004', '750e8400-e29b-41d4-a716-446655440002', 'Thiết kế Bộ nhận diện thương hiệu', 'Tạo logo, color palette, typography cho startup fintech. Cần 5-7 khái niệm logo khác nhau và brand guideline hoàn chỉnh.', '850e8400-e29b-41d4-a716-446655440002', '["Branding", "Logo Design", "Adobe"]', 'open', 1800000, 3000000, 'micro', 5, '["Adobe XD", "Figma", "Illustrator"]', 'intermediate', 2, 0, 'Hà Nội', true, false, ((now())::date + interval '8 day'), now()),
('950e8400-e29b-41d4-a716-446655440005', '750e8400-e29b-41d4-a716-446655440002', 'Thiết kế UI/UX cho Mobile App', 'Thiết kế giao diện cho ứng dụng fitness tracking. Bao gồm wireframe, mockup, prototype. Sử dụng Figma.', '850e8400-e29b-41d4-a716-446655440002', '["UI/UX", "Mobile", "Figma"]', 'open', 3000000, 5000000, 'project', 21, '["Figma", "UI Design", "UX Design"]', 'intermediate', 1, 0, 'Remote', true, false, ((now())::date + interval '12 day'), now()),
('950e8400-e29b-41d4-a716-446655440006', '750e8400-e29b-41d4-a716-446655440003', 'Viết 10 bài SEO Blog (chuẩn EEAT)', 'Viết bài blog về marketing digital, SEO. Mỗi bài 2000+ từ, chuẩn E-E-A-T (Google). Topic từ client cung cấp.', '850e8400-e29b-41d4-a716-446655440003', '["SEO", "Content Writing", "Marketing"]', 'open', 1200000, 2000000, 'micro', 7, '["SEO Writing", "Content Marketing"]', 'beginner', 5, 2, 'Remote', true, true, ((now())::date + interval '12 day'), now()),
('950e8400-e29b-41d4-a716-446655440007', '750e8400-e29b-41d4-a716-446655440003', 'Copywriting cho Email Marketing Campaign', 'Viết 15 email marketing sequences cho sản phẩm SaaS. Email conversion-focused, A/B testing ready.', '850e8400-e29b-41d4-a716-446655440003', '["Copywriting", "Email Marketing"]', 'open', 800000, 1500000, 'micro', 5, '["Copywriting", "Marketing"]', 'beginner', 3, 1, 'Remote', true, false, ((now())::date + interval '10 day'), now()),
('950e8400-e29b-41d4-a716-446655440008', '750e8400-e29b-41d4-a716-446655440003', 'Chạy quảng cáo Facebook Ads - F&B', 'Quản lý campaign Facebook/Instagram Ads cho nhà hàng F&B. Budget: 5-10M/tháng. KPI: bán hàng/booking.', '850e8400-e29b-41d4-a716-446655440004', '["Facebook Ads", "Social Media", "Marketing"]', 'open', 2000000, 3500000, 'short-term', 30, '["Facebook Ads", "Google Analytics"]', 'intermediate', 2, 0, 'Đà Nẵng', false, true, ((now())::date + interval '3 day'), now()),
('950e8400-e29b-41d4-a716-446655440009', '750e8400-e29b-41d4-a716-446655440003', 'Quản lý Social Media - 30 ngày', 'Quản lý TikTok/Instagram cho startup startup. Viết nội dung, lên schedule, theo dõi analytics hàng ngày.', '850e8400-e29b-41d4-a716-446655440004', '["Social Media", "TikTok", "Instagram"]', 'open', 3000000, 5000000, 'short-term', 30, '["Social Media Management", "Content Creation"]', 'intermediate', 2, 0, 'Remote', true, false, ((now())::date + interval '7 day'), now())
