INSERT INTO "FAQs" ("Id", "Question", "Answer", "Category", "OrderIndex") VALUES
('a60e8400-e29b-41d4-a716-446655440001', 'Làm thế nào để xác thực tài khoản sinh viên?', 'Bạn cần cung cấp email đuôi .edu hoặc ảnh thẻ sinh viên. Chúng tôi sẽ xác thực trong vòng 24-48 giờ.', 'verification', 1),
('a60e8400-e29b-41d4-a716-446655440002', 'Tiền từ công việc hoàn thành sẽ về khi nào?', 'Tiền được giữ trong Escrow. Khi doanh nghiệp duyệt hoàn thành, tiền sẽ chuyển vào ví của bạn trong 1-2 ngày.', 'payment', 2),
('a60e8400-e29b-41d4-a716-446655440003', 'Tôi rút tiền ra ngân hàng như thế nào?', 'Vào Ví của bạn > Rút tiền > Nhập thông tin ngân hàng. Yêu cầu rút tiền sẽ được xử lý trong 3-5 ngày.', 'payment', 3),
('a60e8400-e29b-41d4-a716-446655440004', 'Có phí giao dịch không?', 'Không, UniTask không tính phí. Tất cả tiền kiếm được đều về ví của bạn.', 'payment', 4)
